# Chaque valeur contient, sans modification, le code source de l'ancien script.
SCRIPTS = {
    '08_validate_all.py': '"""Classe les candidats des sociétés puis construit un classeur global."""\n\nfrom __future__ import annotations\n\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nimport pandas as pd\n\n\nBASE_DIR = Path(__file__).resolve().parent\nINTERMEDIATE_DIR = BASE_DIR / "data" / "intermediate"\nBY_COMPANY_DIR = BASE_DIR / "data" / "output" / "by_company"\nGLOBAL_OUTPUT = BASE_DIR / "data" / "output" / "variables_financieres_controle_global.xlsx"\nLOG_FILE = BASE_DIR / "logs" / "validate_all.log"\nSUFFIX = "_financial_candidates.xlsx"\n\n\ndef main() -> None:\n    candidate_files = sorted(INTERMEDIATE_DIR.glob(f"*{SUFFIX}"))\n    BY_COMPANY_DIR.mkdir(parents=True, exist_ok=True)\n    LOG_FILE.parent.mkdir(parents=True, exist_ok=True)\n    outputs: list[Path] = []\n\n    with LOG_FILE.open("a", encoding="utf-8") as log:\n        for index, candidate in enumerate(candidate_files, start=1):\n            slug = candidate.name.removesuffix(SUFFIX)\n            message = f"[{index}/{len(candidate_files)}] {slug}"\n            print(message, flush=True)\n            log.write(message + "\\n")\n            log.flush()\n            result = subprocess.run(\n                [\n                    sys.executable,\n                    str(BASE_DIR / "04_build_dataset.py"),\n                    "--company",\n                    slug,\n                    "--top",\n                    "5",\n                    "--output-dir",\n                    str(BY_COMPANY_DIR),\n                ],\n                cwd=BASE_DIR,\n                stdout=log,\n                stderr=log,\n            )\n            output = BY_COMPANY_DIR / f"{slug}_variables_controle.xlsx"\n            if result.returncode == 0 and output.exists():\n                outputs.append(output)\n            else:\n                error = f"ERREUR {result.returncode} : {slug}"\n                print(error, flush=True)\n                log.write(error + "\\n")\n                log.flush()\n\n    sheets: dict[str, list[pd.DataFrame]] = {\n        "Meilleurs candidats": [],\n        "Préselection forte": [],\n        "Contrôle manuel": [],\n        "Couverture": [],\n    }\n    for index, output in enumerate(outputs, start=1):\n        print(f"[CONSOLIDATION {index}/{len(outputs)}] {output.stem}", flush=True)\n        excel = pd.ExcelFile(output)\n        for sheet in sheets:\n            if sheet in excel.sheet_names:\n                sheets[sheet].append(pd.read_excel(output, sheet_name=sheet))\n\n    with pd.ExcelWriter(GLOBAL_OUTPUT, engine="openpyxl") as writer:\n        for sheet, frames in sheets.items():\n            combined = pd.concat(frames, ignore_index=True) if frames else pd.DataFrame()\n            combined.to_excel(writer, sheet_name=sheet[:31], index=False)\n        summary = pd.DataFrame(\n            {\n                "indicateur": [\n                    "fichiers candidats",\n                    "sociétés classées",\n                    "erreurs de classement",\n                ],\n                "valeur": [\n                    len(candidate_files),\n                    len(outputs),\n                    len(candidate_files) - len(outputs),\n                ],\n            }\n        )\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n\n    print(f"Sociétés classées : {len(outputs)}/{len(candidate_files)}")\n    print(f"Sortie globale : {GLOBAL_OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '09_build_strict_provisional.py': '"""Construit une base provisoire stricte, sans prétendre valider les montants."""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport pandas as pd\n\n\nBASE_DIR = Path(__file__).resolve().parent\nSOURCE = BASE_DIR / "data" / "output" / "variables_financieres_controle_global.xlsx"\nOUTPUT = BASE_DIR / "data" / "output" / "variables_financieres_provisoires_strictes.xlsx"\nKEYS = ["societe", "annee_rapport", "type_comptes"]\n\nSTRUCTURAL = {\n    "chiffre_affaires",\n    "total_actif",\n    "capitaux_propres",\n    "total_dettes",\n    "immobilisations_corporelles",\n}\nNON_NEGATIVE = {\n    "chiffre_affaires",\n    "total_actif",\n    "immobilisations_corporelles",\n    "tresorerie_equivalents",\n}\n\n\ndef add_reason(data: pd.DataFrame, mask: pd.Series, reason: str) -> None:\n    data.loc[mask, "motifs_exclusion"] = data.loc[mask, "motifs_exclusion"].map(\n        lambda current: f"{current}; {reason}".strip("; ") if current else reason\n    )\n\n\ndef main() -> None:\n    data = pd.read_excel(SOURCE, sheet_name=1)\n    data["motifs_exclusion"] = ""\n    raw = pd.to_numeric(data["valeur_numerique"], errors="coerce")\n    mad = pd.to_numeric(data["valeur_mad"], errors="coerce")\n\n    add_reason(data, mad.isna(), "montant absent")\n    add_reason(\n        data,\n        raw.between(1900, 2100, inclusive="both"),\n        "nombre probablement issu d\'une année",\n    )\n    add_reason(\n        data,\n        raw.between(0, 31, inclusive="both") & raw.mod(1).eq(0),\n        "nombre probablement issu d\'une date ou d\'un rang",\n    )\n    add_reason(\n        data,\n        data["variable"].isin(STRUCTURAL) & mad.abs().lt(1_000_000),\n        "montant structurel trop faible",\n    )\n    add_reason(\n        data,\n        data["variable"].isin(NON_NEGATIVE) & mad.lt(0),\n        "signe négatif inhabituel",\n    )\n    add_reason(data, mad.abs().gt(5_000_000_000_000), "montant excessif")\n\n    # Si un même montant est attribué à plusieurs variables dans la même\n    # observation, la lecture de proximité a probablement choisi la mauvaise\n    # colonne du tableau. Toutes les occurrences concernées restent à contrôler.\n    duplicates = data.groupby(KEYS + ["valeur_mad"])["variable"].transform("nunique")\n    add_reason(\n        data,\n        duplicates.gt(1),\n        "même montant attribué à plusieurs variables",\n    )\n\n    # Contrôles de ratios lorsque le total actif est disponible dans la même clé.\n    assets = (\n        data[data["variable"].eq("total_actif")]\n        .set_index(KEYS)["valeur_mad"]\n        .to_dict()\n    )\n    revenue = (\n        data[data["variable"].eq("chiffre_affaires")]\n        .set_index(KEYS)["valeur_mad"]\n        .to_dict()\n    )\n    for index, row in data.iterrows():\n        key = tuple(row[column] for column in KEYS)\n        value = abs(float(row["valeur_mad"])) if pd.notna(row["valeur_mad"]) else 0\n        asset = abs(float(assets.get(key, 0) or 0))\n        sales = abs(float(revenue.get(key, 0) or 0))\n        variable = row["variable"]\n        if asset:\n            limits = {\n                "capitaux_propres": 1.5,\n                "immobilisations_corporelles": 1.5,\n                "tresorerie_equivalents": 1.2,\n                "dettes_financieres": 2.0,\n                "total_dettes": 2.0,\n                "impot_differe": 0.5,\n            }\n            if variable in limits and value > asset * limits[variable]:\n                add_reason(\n                    data,\n                    data.index == index,\n                    f"ratio incohérent par rapport au total actif ({limits[variable]:.1f}x)",\n                )\n        if sales and variable in {\n            "resultat_net",\n            "ebit",\n            "resultat_financier",\n            "resultat_avant_impot",\n            "ebitda",\n        } and value > sales * 2:\n            add_reason(\n                data,\n                data.index == index,\n                "résultat supérieur à deux fois le chiffre d\'affaires",\n            )\n\n    strict = data[data["motifs_exclusion"].eq("")].copy()\n    excluded = data[~data["motifs_exclusion"].eq("")].copy()\n    strict["statut_final"] = "selection_stricte_a_verifier"\n    excluded["statut_final"] = "exclu_automatiquement_a_controler"\n\n    wide = strict.pivot_table(\n        index=KEYS,\n        columns="variable",\n        values="valeur_mad",\n        aggfunc="first",\n    ).reset_index()\n    coverage = (\n        strict.groupby(KEYS)["variable"]\n        .nunique()\n        .rename("nombre_variables_selectionnees")\n        .reset_index()\n    )\n    wide = wide.merge(coverage, on=KEYS, how="left")\n\n    summary = pd.DataFrame(\n        {\n            "indicateur": [\n                "présélections entrantes",\n                "sélections strictes à vérifier",\n                "candidats exclus automatiquement",\n                "sociétés dans la sélection stricte",\n                "observations société-année-type",\n            ],\n            "valeur": [\n                len(data),\n                len(strict),\n                len(excluded),\n                strict["societe"].nunique(),\n                len(wide),\n            ],\n        }\n    )\n\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        wide.to_excel(writer, sheet_name="Base provisoire large", index=False)\n        strict.to_excel(writer, sheet_name="Sélection stricte", index=False)\n        excluded.to_excel(writer, sheet_name="Exclusions à contrôler", index=False)\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n    print(summary.to_string(index=False))\n    print(f"Sortie : {OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '10_extract_table_financials.py': '"""Extraction structurée des variables depuis les tableaux des PDF."""\n\nfrom __future__ import annotations\n\nimport argparse\nimport re\nimport unicodedata\nfrom pathlib import Path\n\nimport pandas as pd\nimport fitz\n\n\nBASE_DIR = Path(__file__).resolve().parent\nMANIFEST = BASE_DIR / "data" / "intermediate" / "ammc_reports_manifest_clean.csv"\nOUTPUT_DIR = BASE_DIR / "data" / "intermediate" / "table_candidates"\n\nPATTERNS = {\n    "chiffre_affaires": (r"^chiffre\\s+d[\'’ ]?affaires", r"^ventes\\s+nettes"),\n    "ebit": (r"^resultat\\s+d[\'’ ]?exploitation", r"^resultat\\s+operationnel"),\n    "resultat_financier": (r"^resultat\\s+financier",),\n    "resultat_avant_impot": (\n        r"^resultat\\s+(?:courant\\s+)?avant\\s+impot",\n    ),\n    "resultat_net": (\n        r"^resultat\\s+net(?:\\s+de\\s+l[\'’ ]?ensemble\\s+consolide)?",\n        r"^resultat\\s+de\\s+l[\'’ ]?exercice",\n    ),\n    "total_actif": (r"^total\\s+actif",),\n    "capitaux_propres": (\n        r"^total\\s+(?:des\\s+)?capitaux\\s+propres",\n        r"^capitaux\\s+propres(?:\\s+de\\s+l[\'’ ]?ensemble\\s+consolide)?",\n    ),\n    "total_dettes": (r"^total\\s+(?:des\\s+)?dettes",),\n    "dettes_financieres": (\n        r"^dettes?\\s+financieres?",\n        r"^dettes?\\s+de\\s+financement",\n        r"^emprunts\\s+et\\s+dettes",\n    ),\n    "tresorerie_equivalents": (\n        r"^tresorerie\\s+et\\s+equivalents?",\n        r"^tresorerie\\s+actif",\n        r"^disponibilites",\n    ),\n    "ebitda": (r"^ebitda", r"^excedent\\s+brut\\s+d[\'’ ]?exploitation"),\n    "immobilisations_corporelles": (r"^immobilisations?\\s+corporelles?",),\n    "impot_differe": (r"^impots?\\s+differes?",),\n}\n\nNUMBER_RE = re.compile(\n    r"(?:\\(\\s*)?-?\\d{1,3}(?:[ .\\u00a0]\\d{3})*(?:[,.]\\d+)?(?:\\s*\\))?"\n)\nILLEGAL_EXCEL_RE = re.compile(r"[\\x00-\\x08\\x0b-\\x0c\\x0e-\\x1f]")\n\n\ndef normalize(value: object) -> str:\n    text = unicodedata.normalize("NFKD", str(value or ""))\n    text = "".join(char for char in text if not unicodedata.combining(char))\n    return re.sub(r"\\s+", " ", text.lower().replace("\\u00a0", " ")).strip()\n\n\ndef slugify(value: object) -> str:\n    return re.sub(r"[^a-z0-9]+", "_", normalize(value)).strip("_")\n\n\ndef parse_number(raw: str) -> float | None:\n    text = raw.strip()\n    negative = text.startswith("(") and text.endswith(")")\n    text = text.strip("() ").replace(" ", "").replace("\\u00a0", "")\n    if "," in text and "." in text:\n        if text.rfind(",") > text.rfind("."):\n            text = text.replace(".", "").replace(",", ".")\n        else:\n            text = text.replace(",", "")\n    else:\n        text = text.replace(",", ".")\n    try:\n        value = float(text)\n        return -value if negative else value\n    except ValueError:\n        return None\n\n\ndef unit_info(text: str) -> tuple[str, float]:\n    text = normalize(text)\n    if re.search(r"milliards?|gdh", text):\n        return "milliards MAD", 1_000_000_000.0\n    if re.search(r"millions?|\\bmmad\\b|\\bmdh\\b", text):\n        return "millions MAD", 1_000_000.0\n    if re.search(r"milliers?|\\bkmad\\b|\\bkdh\\b", text):\n        return "milliers MAD", 1_000.0\n    if re.search(r"\\bmad\\b|dirhams?|\\bdhs?\\b", text):\n        return "MAD", 1.0\n    return "inconnue", 1.0\n\n\ndef years_from_header(text: str, report_year: int) -> list[int]:\n    # Les états annuels présentent normalement l\'exercice courant puis le\n    # comparatif N-1. Les autres années visibles sur la page appartiennent\n    # souvent à des notes, dates ou historiques et ne doivent pas décaler les\n    # colonnes numériques de la ligne.\n    return [report_year, report_year - 1]\n\n\ndef account_type(text: str, report_type: str) -> str:\n    combined = normalize(text + " " + report_type)\n    if "consolide" in combined:\n        return "consolides"\n    if "social" in combined:\n        return "sociaux"\n    return "a_controler"\n\n\ndef match_variable(row_text: str) -> tuple[str, re.Match] | None:\n    normalized = normalize(row_text)\n    for variable, patterns in PATTERNS.items():\n        for pattern in patterns:\n            match = re.search(pattern, normalized)\n            if match:\n                return variable, match\n    return None\n\n\ndef extract_report(row: pd.Series) -> list[dict]:\n    path = BASE_DIR / str(row["local_path"])\n    report_year = int(row["year"])\n    results: list[dict] = []\n    fast_document = fitz.open(path)\n    page_texts = [page.get_text("text") for page in fast_document]\n    fast_document.close()\n    keywords = (\n        "chiffre",\n        "resultat",\n        "actif",\n        "capitaux",\n        "dette",\n        "tresorerie",\n        "ebitda",\n        "excedent brut",\n        "immobilisation",\n        "impot differe",\n    )\n    candidate_pages = [\n        index\n        for index, text in enumerate(page_texts)\n        if any(keyword in normalize(text) for keyword in keywords)\n    ]\n    for page_index in candidate_pages:\n        page_number = page_index + 1\n        page_text = page_texts[page_index]\n        lines = [line.strip() for line in page_text.splitlines() if line.strip()]\n        header_text = " | ".join(lines[:45])\n        years = years_from_header(header_text, report_year)\n        page_unit, page_multiplier = unit_info(page_text[:3000])\n        page_accounts = account_type(page_text, str(row["report_type"]))\n        for row_index, line in enumerate(lines, start=1):\n            matched = match_variable(line)\n            if not matched:\n                continue\n            variable, match = matched\n            unit, multiplier = "inconnue", 1.0\n            for nearby_line in reversed(\n                lines[max(0, row_index - 41): row_index]\n            ):\n                nearby_unit, nearby_multiplier = unit_info(nearby_line)\n                if nearby_unit != "inconnue":\n                    unit, multiplier = nearby_unit, nearby_multiplier\n                    break\n            if unit == "inconnue":\n                unit, multiplier = page_unit, page_multiplier\n            # Les valeurs sont souvent placées dans les 2 à 4 lignes suivantes\n            # par l\'ordre de lecture interne du PDF.\n            row_text = " ".join(lines[row_index - 1: row_index + 4])\n            normalized_row = normalize(row_text)\n            suffix = normalized_row[match.end():]\n            raw_values = NUMBER_RE.findall(suffix)\n            values = [\n                (raw, value)\n                for raw in raw_values\n                if (value := parse_number(raw)) is not None\n            ]\n            if not values or len(values) > 4:\n                continue\n            for position, (raw, value) in enumerate(values[: len(years)]):\n                year = years[position] if position < len(years) else report_year - position\n                if not 2000 <= year <= 2025:\n                    continue\n                results.append(\n                    {\n                        "societe": row["requested_company"],\n                        "annee": year,\n                        "annee_rapport": report_year,\n                        "type_comptes": page_accounts,\n                        "variable": variable,\n                        "valeur_brute": raw,\n                        "valeur_numerique": value,\n                        "unite": unit,\n                        "multiplicateur_mad": multiplier,\n                        "valeur_mad": value * multiplier,\n                        "page_pdf": page_number,\n                        "table_index": 0,\n                        "row_index": row_index,\n                        "ligne_tableau": row_text[:1200],\n                        "source_pdf": row["local_path"],\n                        "report_type": row["report_type"],\n                        "score_source": 90 if unit != "inconnue" else 75,\n                        "statut_validation": "ligne_tableau_a_verifier",\n                    }\n                )\n    return results\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--company", required=True)\n    args = parser.parse_args()\n    manifest = pd.read_csv(MANIFEST)\n    company_slug = slugify(args.company)\n    selected = manifest[\n        manifest["requested_company"].map(slugify).eq(company_slug)\n        & manifest["status"].eq("downloaded")\n    ]\n    if selected.empty:\n        raise SystemExit(f"Aucun rapport valide : {args.company}")\n    all_rows: list[dict] = []\n    for index, (_, report) in enumerate(selected.iterrows(), start=1):\n        print(f"[{index}/{len(selected)}] {report[\'local_path\']}", flush=True)\n        all_rows.extend(extract_report(report))\n    output = OUTPUT_DIR / f"{company_slug}_table_candidates.xlsx"\n    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)\n    dataframe = pd.DataFrame(all_rows)\n    for column in dataframe.select_dtypes(include="object").columns:\n        dataframe[column] = dataframe[column].map(\n            lambda value: ILLEGAL_EXCEL_RE.sub("", value)\n            if isinstance(value, str)\n            else value\n        )\n    dataframe.to_excel(output, index=False)\n    print(f"Candidats de tableaux : {len(all_rows)}")\n    print(f"Sortie : {output}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '11_extract_tables_all.py': '"""Lance l\'extraction structurée des lignes de tableaux pour toutes les sociétés."""\n\nfrom __future__ import annotations\n\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nimport pandas as pd\n\n\nBASE_DIR = Path(__file__).resolve().parent\nMANIFEST = BASE_DIR / "data" / "intermediate" / "ammc_reports_manifest_clean.csv"\nLOG_FILE = BASE_DIR / "logs" / "extract_tables_all.log"\n\n\ndef main() -> None:\n    manifest = pd.read_csv(MANIFEST)\n    companies = sorted(\n        manifest.loc[manifest["status"].eq("downloaded"), "requested_company"]\n        .dropna()\n        .unique()\n    )\n    LOG_FILE.parent.mkdir(parents=True, exist_ok=True)\n    with LOG_FILE.open("a", encoding="utf-8") as log:\n        for index, company in enumerate(companies, start=1):\n            message = f"[{index}/{len(companies)}] {company}"\n            print(message, flush=True)\n            log.write(message + "\\n")\n            log.flush()\n            result = subprocess.run(\n                [\n                    sys.executable,\n                    str(BASE_DIR / "10_extract_table_financials.py"),\n                    "--company",\n                    str(company),\n                ],\n                cwd=BASE_DIR,\n                stdout=log,\n                stderr=log,\n            )\n            if result.returncode:\n                error = f"ERREUR {result.returncode} : {company}"\n                print(error, flush=True)\n                log.write(error + "\\n")\n                log.flush()\n\n    print("[CONSOLIDATION] Reconstruction du fichier structuré global.", flush=True)\n    subprocess.run(\n        [sys.executable, str(BASE_DIR / "12_consolidate_table_candidates.py")],\n        cwd=BASE_DIR,\n        check=True,\n    )\n    for script in (\n        "13_finalize_financial_base.py",\n        "14_audit_completeness.py",\n        "15_prepare_review_batches.py",\n    ):\n        print(f"[PIPELINE] {script}", flush=True)\n        subprocess.run(\n            [sys.executable, str(BASE_DIR / script)],\n            cwd=BASE_DIR,\n            check=True,\n        )\n\n\nif __name__ == "__main__":\n    main()\n',
    '12_consolidate_table_candidates.py': '"""Consolide et filtre les candidats issus des lignes de tableaux."""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport pandas as pd\n\n\nBASE_DIR = Path(__file__).resolve().parent\nINPUT_DIR = BASE_DIR / "data" / "intermediate" / "table_candidates"\nOUTPUT = BASE_DIR / "data" / "output" / "variables_financieres_tableaux_structurees.xlsx"\nKEYS = ["societe", "annee", "type_comptes", "variable"]\nSTRUCTURAL = {\n    "chiffre_affaires",\n    "total_actif",\n    "capitaux_propres",\n    "total_dettes",\n    "immobilisations_corporelles",\n}\nNON_NEGATIVE = {\n    "chiffre_affaires",\n    "total_actif",\n    "immobilisations_corporelles",\n    "tresorerie_equivalents",\n}\n\n\ndef add_reason(data: pd.DataFrame, mask: pd.Series, reason: str) -> None:\n    data.loc[mask, "motifs_exclusion"] = data.loc[mask, "motifs_exclusion"].map(\n        lambda current: f"{current}; {reason}".strip("; ") if current else reason\n    )\n\n\ndef main() -> None:\n    files = sorted(INPUT_DIR.glob("*_table_candidates.xlsx"))\n    frames = []\n    for index, file in enumerate(files, start=1):\n        print(f"[{index}/{len(files)}] {file.name}")\n        frame = pd.read_excel(file)\n        if not frame.empty:\n            frames.append(frame)\n    data = pd.concat(frames, ignore_index=True) if frames else pd.DataFrame()\n    if data.empty:\n        raise SystemExit("Aucun candidat structuré.")\n\n    data.drop_duplicates(\n        ["source_pdf", "page_pdf", "row_index", "annee", "variable", "valeur_mad"],\n        inplace=True,\n    )\n    data["motifs_exclusion"] = ""\n    raw = pd.to_numeric(data["valeur_numerique"], errors="coerce")\n    mad = pd.to_numeric(data["valeur_mad"], errors="coerce")\n    add_reason(data, mad.isna(), "montant absent")\n    add_reason(data, raw.between(1900, 2100), "nombre probablement issu d\'une année")\n    add_reason(\n        data,\n        raw.between(0, 31) & raw.mod(1).eq(0),\n        "nombre probablement issu d\'une date ou d\'un rang",\n    )\n    add_reason(\n        data,\n        data["variable"].isin(STRUCTURAL) & mad.abs().lt(1_000_000),\n        "montant structurel trop faible",\n    )\n    add_reason(\n        data,\n        data["variable"].isin(NON_NEGATIVE) & mad.lt(0),\n        "signe négatif inhabituel",\n    )\n    add_reason(data, mad.abs().gt(5_000_000_000_000), "montant excessif")\n\n    data["score_classement"] = pd.to_numeric(\n        data["score_source"], errors="coerce"\n    ).fillna(0)\n    data.loc[data["annee"].eq(data["annee_rapport"]), "score_classement"] += 30\n    data.loc[data["unite"].ne("inconnue"), "score_classement"] += 15\n    data.loc[data["type_comptes"].isin(["sociaux", "consolides"]), "score_classement"] += 15\n    data.loc[data["motifs_exclusion"].ne(""), "score_classement"] -= 100\n\n    usable = data[data["motifs_exclusion"].eq("")].copy()\n    usable.sort_values(\n        KEYS + ["score_classement", "annee_rapport"],\n        ascending=[True, True, True, True, False, False],\n        inplace=True,\n    )\n    usable["rang_candidat"] = usable.groupby(KEYS).cumcount() + 1\n    best = usable[usable["rang_candidat"].eq(1)].copy()\n    best["statut_validation"] = "meilleur_tableau_a_confirmer"\n    excluded = data[data["motifs_exclusion"].ne("")].copy()\n\n    wide = best.pivot_table(\n        index=["societe", "annee", "type_comptes"],\n        columns="variable",\n        values="valeur_mad",\n        aggfunc="first",\n    ).reset_index()\n    coverage = (\n        best.groupby(["societe", "annee", "type_comptes"])["variable"]\n        .nunique()\n        .rename("nombre_variables")\n        .reset_index()\n    )\n    wide = wide.merge(coverage, on=["societe", "annee", "type_comptes"], how="left")\n    summary = pd.DataFrame(\n        {\n            "indicateur": [\n                "fichiers sociétés",\n                "candidats structurés bruts",\n                "candidats utilisables",\n                "meilleurs candidats",\n                "candidats exclus",\n                "sociétés représentées",\n                "observations société-année-type",\n            ],\n            "valeur": [\n                len(files),\n                len(data),\n                len(usable),\n                len(best),\n                len(excluded),\n                best["societe"].nunique(),\n                len(wide),\n            ],\n        }\n    )\n\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        wide.to_excel(writer, sheet_name="Base large tableaux", index=False)\n        best.to_excel(writer, sheet_name="Meilleurs tableaux", index=False)\n        usable[usable["rang_candidat"].le(5)].to_excel(\n            writer, sheet_name="Top 5 tableaux", index=False\n        )\n        excluded.to_excel(writer, sheet_name="Exclusions", index=False)\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n    print(summary.to_string(index=False))\n    print(f"Sortie : {OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '13_finalize_financial_base.py': '"""Résout les périmètres et applique les contrôles comptables finaux."""\n\nfrom __future__ import annotations\n\nimport re\nimport unicodedata\nfrom pathlib import Path\n\nimport pandas as pd\n\n\nBASE_DIR = Path(__file__).resolve().parent\nSOURCE = BASE_DIR / "data" / "output" / "variables_financieres_tableaux_structurees.xlsx"\nCOMPANIES = BASE_DIR / "data" / "input" / "societes.xlsx"\nOUTPUT = BASE_DIR / "data" / "output" / "variables_financieres_base_prevalidee.xlsx"\nKEYS = ["societe", "annee", "type_comptes_resolu"]\n\n\ndef normalize(value: object) -> str:\n    text = unicodedata.normalize("NFKD", str(value or ""))\n    text = "".join(char for char in text if not unicodedata.combining(char))\n    return re.sub(r"\\s+", " ", re.sub(r"[^a-z0-9]+", " ", text.lower())).strip()\n\n\ndef add_alert(data: pd.DataFrame, mask: pd.Series, message: str, severe: bool = False) -> None:\n    data.loc[mask, "alertes_finales"] = data.loc[mask, "alertes_finales"].map(\n        lambda current: f"{current}; {message}".strip("; ") if current else message\n    )\n    data.loc[mask, "nombre_alertes_finales"] += 1\n    if severe:\n        data.loc[mask, "alerte_severe"] = True\n\n\ndef resolve_accounts(data: pd.DataFrame) -> pd.DataFrame:\n    data = data.copy()\n    data["type_comptes_resolu"] = data["type_comptes"]\n    data["methode_resolution_comptes"] = data["type_comptes"].map(\n        lambda value: "explicite_page_ou_rapport"\n        if value in {"sociaux", "consolides"}\n        else "non_resolu"\n    )\n    for source, indexes in data.groupby("source_pdf").groups.items():\n        group = data.loc[indexes]\n        known = group[group["type_comptes"].isin(["sociaux", "consolides"])]\n        unknown = group[group["type_comptes"].eq("a_controler")]\n        if unknown.empty or known.empty:\n            continue\n        known_types = set(known["type_comptes"])\n        for index, row in unknown.iterrows():\n            distances = (known["page_pdf"] - row["page_pdf"]).abs()\n            minimum = distances.min()\n            nearest = set(known.loc[distances.eq(minimum), "type_comptes"])\n            if minimum <= 8 and len(nearest) == 1:\n                data.at[index, "type_comptes_resolu"] = next(iter(nearest))\n                data.at[index, "methode_resolution_comptes"] = "page_connue_la_plus_proche"\n            elif len(known_types) == 1:\n                data.at[index, "type_comptes_resolu"] = next(iter(known_types))\n                data.at[index, "methode_resolution_comptes"] = "type_unique_dans_le_pdf"\n    return data\n\n\ndef main() -> None:\n    data = pd.read_excel(SOURCE, sheet_name=1)\n    data = resolve_accounts(data)\n    data["alertes_finales"] = ""\n    data["nombre_alertes_finales"] = 0\n    data["alerte_severe"] = False\n\n    add_alert(\n        data,\n        data["type_comptes_resolu"].eq("a_controler"),\n        "type de comptes non résolu",\n    )\n    add_alert(data, data["unite"].eq("inconnue"), "unité inconnue")\n\n    # Détecter un même montant sélectionné pour plusieurs variables dans la clé.\n    duplicate_values = data.groupby(KEYS + ["valeur_mad"])["variable"].transform("nunique")\n    add_alert(\n        data,\n        duplicate_values.gt(1),\n        "même montant attribué à plusieurs variables",\n        severe=True,\n    )\n\n    # Contrôles croisés par observation.\n    wide = data.pivot_table(\n        index=KEYS,\n        columns="variable",\n        values="valeur_mad",\n        aggfunc="first",\n    )\n    for key, row in wide.iterrows():\n        mask = pd.Series(True, index=data.index)\n        for column, value in zip(KEYS, key):\n            mask &= data[column].eq(value)\n        asset = abs(float(row.get("total_actif", 0) or 0))\n        equity = abs(float(row.get("capitaux_propres", 0) or 0))\n        debt = abs(float(row.get("total_dettes", 0) or 0))\n        if asset:\n            ratio_limits = {\n                "capitaux_propres": 1.5,\n                "immobilisations_corporelles": 1.5,\n                "tresorerie_equivalents": 1.2,\n                "dettes_financieres": 2.0,\n                "total_dettes": 2.0,\n                "impot_differe": 0.5,\n            }\n            for variable, limit in ratio_limits.items():\n                value = abs(float(row.get(variable, 0) or 0))\n                if value > asset * limit:\n                    add_alert(\n                        data,\n                        mask & data["variable"].eq(variable),\n                        f"ratio supérieur à {limit:.1f} fois le total actif",\n                        severe=value > asset * limit * 2,\n                    )\n            if equity and debt:\n                gap = abs(asset - equity - debt) / asset\n                if gap > 0.35:\n                    add_alert(\n                        data,\n                        mask & data["variable"].isin(\n                            ["total_actif", "capitaux_propres", "total_dettes"]\n                        ),\n                        f"équation bilan non vérifiée, écart {gap:.0%}",\n                    )\n        sales = abs(float(row.get("chiffre_affaires", 0) or 0))\n        if sales:\n            for variable in (\n                "resultat_net",\n                "ebit",\n                "resultat_financier",\n                "resultat_avant_impot",\n                "ebitda",\n            ):\n                value = abs(float(row.get(variable, 0) or 0))\n                if value > sales * 2:\n                    add_alert(\n                        data,\n                        mask & data["variable"].eq(variable),\n                        "résultat supérieur à deux fois le chiffre d\'affaires",\n                        severe=value > sales * 5,\n                    )\n\n    # Continuité annuelle : variation supérieure à 10x sur deux années consécutives.\n    ordered = data.sort_values(["societe", "type_comptes_resolu", "variable", "annee"])\n    group_columns = ["societe", "type_comptes_resolu", "variable"]\n    for _, group in ordered.groupby(group_columns):\n        previous = None\n        for index, row in group.iterrows():\n            value = abs(float(row["valeur_mad"])) if pd.notna(row["valeur_mad"]) else 0\n            year = int(row["annee"])\n            if previous and year - previous[0] == 1 and value and previous[1]:\n                ratio = max(value / previous[1], previous[1] / value)\n                if ratio > 10:\n                    add_alert(\n                        data,\n                        data.index == index,\n                        f"variation annuelle extrême x{ratio:.1f}",\n                        severe=ratio > 100,\n                    )\n            previous = (year, value)\n\n    data["statut_final"] = "a_confirmer_manuellement"\n    data.loc[data["alerte_severe"], "statut_final"] = "a_rejeter_ou_corriger"\n    data.loc[\n        data["nombre_alertes_finales"].eq(0)\n        & data["type_comptes_resolu"].isin(["sociaux", "consolides"])\n        & data["score_classement"].ge(120),\n        "statut_final",\n    ] = "prevalide_automatiquement"\n\n    # Ajouter le secteur depuis la liste de référence.\n    companies = pd.read_excel(COMPANIES, sheet_name="Societes")\n    sector_map = {\n        normalize(row.iloc[0]): row.iloc[1]\n        for _, row in companies.iterrows()\n        if pd.notna(row.iloc[0])\n    }\n    data.insert(\n        1,\n        "secteur",\n        data["societe"].map(lambda value: sector_map.get(normalize(value), "")),\n    )\n\n    prevalidated = data[data["statut_final"].eq("prevalide_automatiquement")].copy()\n    manual = data[data["statut_final"].eq("a_confirmer_manuellement")].copy()\n    rejected = data[data["statut_final"].eq("a_rejeter_ou_corriger")].copy()\n    final_wide = prevalidated.pivot_table(\n        index=["societe", "secteur", "annee", "type_comptes_resolu"],\n        columns="variable",\n        values="valeur_mad",\n        aggfunc="first",\n    ).reset_index()\n    counts = (\n        prevalidated.groupby(["societe", "annee", "type_comptes_resolu"])["variable"]\n        .nunique()\n        .rename("nombre_variables_prevalidees")\n        .reset_index()\n    )\n    final_wide = final_wide.merge(\n        counts,\n        on=["societe", "annee", "type_comptes_resolu"],\n        how="left",\n    )\n    summary = pd.DataFrame(\n        {\n            "indicateur": [\n                "meilleurs candidats entrants",\n                "types de comptes résolus",\n                "types restant à contrôler",\n                "valeurs prévalidées automatiquement",\n                "valeurs à confirmer manuellement",\n                "valeurs à rejeter ou corriger",\n                "observations prévalidées société-année-type",\n                "sociétés dans la base prévalidée",\n            ],\n            "valeur": [\n                len(data),\n                data["type_comptes_resolu"].isin(["sociaux", "consolides"]).sum(),\n                data["type_comptes_resolu"].eq("a_controler").sum(),\n                len(prevalidated),\n                len(manual),\n                len(rejected),\n                len(final_wide),\n                prevalidated["societe"].nunique(),\n            ],\n        }\n    )\n\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        final_wide.to_excel(writer, sheet_name="Base prévalidée large", index=False)\n        prevalidated.to_excel(writer, sheet_name="Valeurs prévalidées", index=False)\n        manual.to_excel(writer, sheet_name="Contrôle manuel", index=False)\n        rejected.to_excel(writer, sheet_name="Rejets à corriger", index=False)\n        data.to_excel(writer, sheet_name="Toutes les valeurs", index=False)\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n    print(summary.to_string(index=False))\n    print(f"Sortie : {OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '14_audit_completeness.py': '"""Établit le plan de complétion de la base financière annuelle."""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport pandas as pd\n\n\nBASE_DIR = Path(__file__).resolve().parent\nSOURCE = BASE_DIR / "data" / "output" / "variables_financieres_base_prevalidee.xlsx"\nOUTPUT = BASE_DIR / "data" / "output" / "plan_completion_variables_2010_2025.xlsx"\n\nVARIABLES = [\n    "chiffre_affaires",\n    "ebit",\n    "resultat_financier",\n    "resultat_avant_impot",\n    "resultat_net",\n    "total_actif",\n    "capitaux_propres",\n    "total_dettes",\n    "dettes_financieres",\n    "tresorerie_equivalents",\n    "ebitda",\n    "immobilisations_corporelles",\n    "impot_differe",\n]\nPRIORITY = {\n    "resultat_avant_impot": 1,\n    "chiffre_affaires": 2,\n    "ebit": 3,\n    "resultat_financier": 4,\n    "total_actif": 5,\n    "capitaux_propres": 6,\n    "resultat_net": 7,\n    "dettes_financieres": 8,\n    "total_dettes": 9,\n    "tresorerie_equivalents": 10,\n    "immobilisations_corporelles": 11,\n    "ebitda": 12,\n    "impot_differe": 13,\n}\n\n\ndef main() -> None:\n    wide = pd.read_excel(SOURCE, sheet_name=0)\n    wide = wide[wide["annee"].between(2010, 2025)].copy()\n    for variable in VARIABLES:\n        if variable not in wide:\n            wide[variable] = pd.NA\n\n    long = wide.melt(\n        id_vars=["societe", "secteur", "annee", "type_comptes_resolu"],\n        value_vars=VARIABLES,\n        var_name="variable",\n        value_name="valeur_mad",\n    )\n    long["disponible"] = long["valeur_mad"].notna()\n    missing = long[~long["disponible"]].copy()\n    missing["priorite"] = missing["variable"].map(PRIORITY)\n    missing.sort_values(\n        ["priorite", "societe", "annee", "type_comptes_resolu"],\n        inplace=True,\n    )\n\n    variable_coverage = (\n        long.groupby("variable")["disponible"]\n        .agg(["sum", "count"])\n        .rename(columns={"sum": "valeurs_disponibles", "count": "observations_attendues"})\n        .reset_index()\n    )\n    variable_coverage["valeurs_manquantes"] = (\n        variable_coverage["observations_attendues"]\n        - variable_coverage["valeurs_disponibles"]\n    )\n    variable_coverage["taux_couverture"] = (\n        variable_coverage["valeurs_disponibles"]\n        / variable_coverage["observations_attendues"]\n    )\n    variable_coverage["priorite"] = variable_coverage["variable"].map(PRIORITY)\n    variable_coverage.sort_values("priorite", inplace=True)\n\n    observation_coverage = (\n        long.groupby(["societe", "secteur", "annee", "type_comptes_resolu"])["disponible"]\n        .sum()\n        .rename("nombre_variables_disponibles")\n        .reset_index()\n    )\n    observation_coverage["nombre_variables_manquantes"] = (\n        len(VARIABLES) - observation_coverage["nombre_variables_disponibles"]\n    )\n    observation_coverage["taux_completion"] = (\n        observation_coverage["nombre_variables_disponibles"] / len(VARIABLES)\n    )\n    observation_coverage.sort_values(\n        ["taux_completion", "societe", "annee"],\n        ascending=[False, True, True],\n        inplace=True,\n    )\n\n    company_coverage = (\n        observation_coverage.groupby(["societe", "secteur"])\n        .agg(\n            observations=("annee", "size"),\n            variables_disponibles=("nombre_variables_disponibles", "sum"),\n            variables_manquantes=("nombre_variables_manquantes", "sum"),\n            taux_completion_moyen=("taux_completion", "mean"),\n            premiere_annee=("annee", "min"),\n            derniere_annee=("annee", "max"),\n        )\n        .reset_index()\n        .sort_values("taux_completion_moyen", ascending=False)\n    )\n\n    manual = pd.read_excel(SOURCE, sheet_name=2)\n    manual = manual[manual["annee"].between(2010, 2025)].copy()\n    manual["priorite_variable"] = manual["variable"].map(PRIORITY).fillna(99)\n    manual.sort_values(\n        ["priorite_variable", "score_classement"],\n        ascending=[True, False],\n        inplace=True,\n    )\n\n    summary = pd.DataFrame(\n        {\n            "indicateur": [\n                "observations prévalidées 2010-2025",\n                "sociétés représentées",\n                "valeurs disponibles sur 13 variables",\n                "valeurs manquantes sur 13 variables",\n                "taux global de complétude",\n                "candidats manuels disponibles 2010-2025",\n            ],\n            "valeur": [\n                len(wide),\n                wide["societe"].nunique(),\n                int(long["disponible"].sum()),\n                int((~long["disponible"]).sum()),\n                float(long["disponible"].mean()),\n                len(manual),\n            ],\n        }\n    )\n\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n        variable_coverage.to_excel(writer, sheet_name="Couverture variables", index=False)\n        company_coverage.to_excel(writer, sheet_name="Couverture sociétés", index=False)\n        observation_coverage.to_excel(writer, sheet_name="Couverture observations", index=False)\n        missing.to_excel(writer, sheet_name="Valeurs manquantes", index=False)\n        manual.to_excel(writer, sheet_name="File contrôle priorisée", index=False)\n    print(summary.to_string(index=False))\n    print(f"Sortie : {OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '15_prepare_review_batches.py': '"""Prépare des lots de contrôle manuel ciblés sur les valeurs manquantes."""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport pandas as pd\n\n\nBASE_DIR = Path(__file__).resolve().parent\nPLAN = BASE_DIR / "data" / "output" / "plan_completion_variables_2010_2025.xlsx"\nOUTPUT = BASE_DIR / "data" / "output" / "lots_controle_prioritaire.xlsx"\nPRIORITY_VARIABLES = [\n    "resultat_avant_impot",\n    "chiffre_affaires",\n    "ebit",\n    "resultat_financier",\n    "total_actif",\n    "capitaux_propres",\n]\nKEYS = ["societe", "annee", "type_comptes_resolu", "variable"]\n\n\ndef main() -> None:\n    missing = pd.read_excel(PLAN, sheet_name=4)\n    manual = pd.read_excel(PLAN, sheet_name=5)\n    missing_keys = missing[\n        missing["variable"].isin(PRIORITY_VARIABLES)\n    ][KEYS].drop_duplicates()\n    candidates = manual.merge(missing_keys, on=KEYS, how="inner")\n    candidates.sort_values(\n        ["priorite_variable", "score_classement", "nombre_alertes_finales"],\n        ascending=[True, False, True],\n        inplace=True,\n    )\n    candidates["rang_pour_valeur_manquante"] = (\n        candidates.groupby(KEYS).cumcount() + 1\n    )\n    top = candidates[candidates["rang_pour_valeur_manquante"].le(3)].copy()\n    top["decision_controle"] = ""\n    top["valeur_corrigee_mad"] = pd.NA\n    top["commentaire_controle"] = ""\n    top["chemin_pdf_absolu"] = top["source_pdf"].map(\n        lambda value: str(BASE_DIR / str(value))\n    )\n\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        for index, variable in enumerate(PRIORITY_VARIABLES, start=1):\n            subset = top[top["variable"].eq(variable)].copy()\n            subset.to_excel(\n                writer,\n                sheet_name=f"{index}_{variable}"[:31],\n                index=False,\n            )\n        top.to_excel(writer, sheet_name="Tous candidats prioritaires", index=False)\n        summary = (\n            top.groupby("variable")\n            .agg(\n                candidats=("variable", "size"),\n                valeurs_manquantes_couvertes=("rang_pour_valeur_manquante", lambda s: (s == 1).sum()),\n                societes=("societe", "nunique"),\n            )\n            .reset_index()\n        )\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n    print(f"Candidats préparés : {len(top)}")\n    print(f"Valeurs manquantes avec au moins un candidat : {(top[\'rang_pour_valeur_manquante\'] == 1).sum()}")\n    print(f"Sortie : {OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '16_accept_unambiguous_comparatives.py': '"""Intègre les comparatifs N-1 sans alerte dans une nouvelle base prévalidée."""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport pandas as pd\n\n\nBASE_DIR = Path(__file__).resolve().parent\nBASE_FILE = BASE_DIR / "data" / "output" / "variables_financieres_base_prevalidee.xlsx"\nREVIEW_FILE = BASE_DIR / "data" / "output" / "lots_controle_prioritaire.xlsx"\nOUTPUT = BASE_DIR / "data" / "output" / "variables_financieres_base_prevalidee_v2.xlsx"\nREMAINING = BASE_DIR / "data" / "output" / "lots_controle_prioritaire_restants.xlsx"\nKEYS = ["societe", "annee", "type_comptes_resolu", "variable"]\n\n\ndef main() -> None:\n    prevalidated = pd.read_excel(BASE_FILE, sheet_name=1)\n    review = pd.read_excel(REVIEW_FILE, sheet_name=6)\n    accepted = review[\n        review["alertes_finales"].fillna("").eq("")\n        & review["unite"].ne("inconnue")\n        & review["type_comptes_resolu"].isin(["sociaux", "consolides"])\n        & review["score_classement"].eq(105)\n        & review["annee_rapport"].eq(review["annee"] + 1)\n    ].copy()\n    accepted.sort_values(\n        KEYS + ["rang_pour_valeur_manquante"],\n        inplace=True,\n    )\n    accepted.drop_duplicates(KEYS, keep="first", inplace=True)\n    accepted["statut_final"] = "prevalide_comparatif_n_1_sans_alerte"\n    accepted["methode_validation"] = (\n        "ligne structurée; unité connue; périmètre résolu; N-1; aucune alerte"\n    )\n\n    common_columns = sorted(set(prevalidated.columns) | set(accepted.columns))\n    for column in common_columns:\n        if column not in prevalidated:\n            prevalidated[column] = pd.NA\n        if column not in accepted:\n            accepted[column] = pd.NA\n    combined = pd.concat(\n        [prevalidated[common_columns], accepted[common_columns]],\n        ignore_index=True,\n    )\n    combined.sort_values(KEYS, inplace=True)\n    combined.drop_duplicates(KEYS, keep="first", inplace=True)\n\n    wide = combined.pivot_table(\n        index=["societe", "secteur", "annee", "type_comptes_resolu"],\n        columns="variable",\n        values="valeur_mad",\n        aggfunc="first",\n    ).reset_index()\n    counts = (\n        combined.groupby(["societe", "annee", "type_comptes_resolu"])["variable"]\n        .nunique()\n        .rename("nombre_variables_prevalidees")\n        .reset_index()\n    )\n    wide = wide.merge(\n        counts,\n        on=["societe", "annee", "type_comptes_resolu"],\n        how="left",\n    )\n\n    accepted_keys = accepted[KEYS].assign(acceptee=True)\n    remaining = review.merge(accepted_keys, on=KEYS, how="left")\n    remaining = remaining[remaining["acceptee"].isna()].drop(columns=["acceptee"])\n    summary = pd.DataFrame(\n        {\n            "indicateur": [\n                "valeurs prévalidées initiales",\n                "comparatifs N-1 acceptés",\n                "valeurs prévalidées v2",\n                "observations société-année-type v2",\n                "candidats prioritaires restants",\n            ],\n            "valeur": [\n                len(prevalidated),\n                len(accepted),\n                len(combined),\n                len(wide),\n                len(remaining),\n            ],\n        }\n    )\n\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        wide.to_excel(writer, sheet_name="Base prévalidée large", index=False)\n        combined.to_excel(writer, sheet_name="Valeurs prévalidées", index=False)\n        accepted.to_excel(writer, sheet_name="Ajouts comparatifs N-1", index=False)\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n    with pd.ExcelWriter(REMAINING, engine="openpyxl") as writer:\n        remaining.to_excel(writer, sheet_name="Candidats restants", index=False)\n        (\n            remaining.groupby("variable")\n            .size()\n            .rename("nombre")\n            .reset_index()\n            .to_excel(writer, sheet_name="Résumé", index=False)\n        )\n    print(summary.to_string(index=False))\n    print(f"Base v2 : {OUTPUT}")\n    print(f"Contrôles restants : {REMAINING}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '17_infer_same_page_units.py': '"""Complète les unités inconnues lorsque la page possède une unité unique connue."""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport pandas as pd\n\n\nBASE_DIR = Path(__file__).resolve().parent\nBASE_V2 = BASE_DIR / "data" / "output" / "variables_financieres_base_prevalidee_v2.xlsx"\nALL_VALUES = BASE_DIR / "data" / "output" / "variables_financieres_base_prevalidee.xlsx"\nREMAINING = BASE_DIR / "data" / "output" / "lots_controle_prioritaire_restants.xlsx"\nOUTPUT = BASE_DIR / "data" / "output" / "variables_financieres_base_prevalidee_v3.xlsx"\nREMAINING_OUTPUT = BASE_DIR / "data" / "output" / "lots_controle_prioritaire_restants_v3.xlsx"\nKEYS = ["societe", "annee", "type_comptes_resolu", "variable"]\nMULTIPLIERS = {\n    "MAD": 1.0,\n    "milliers MAD": 1_000.0,\n    "millions MAD": 1_000_000.0,\n    "milliards MAD": 1_000_000_000.0,\n}\n\n\ndef main() -> None:\n    base = pd.read_excel(BASE_V2, sheet_name=1)\n    remaining = pd.read_excel(REMAINING, sheet_name=0)\n    all_values = pd.read_excel(ALL_VALUES, sheet_name=4)\n    known = all_values[\n        all_values["unite"].isin(MULTIPLIERS)\n    ]\n    page_units = known.groupby(["source_pdf", "page_pdf"])["unite"].agg(\n        lambda series: sorted(set(series))\n    )\n\n    inferred_rows = []\n    for index, row in remaining.iterrows():\n        if row["alertes_finales"] != "unité inconnue":\n            continue\n        units = page_units.get((row["source_pdf"], row["page_pdf"]), [])\n        if len(units) != 1:\n            continue\n        unit = units[0]\n        corrected = row.copy()\n        corrected["unite"] = unit\n        corrected["multiplicateur_mad"] = MULTIPLIERS[unit]\n        corrected["valeur_mad"] = (\n            float(corrected["valeur_numerique"]) * MULTIPLIERS[unit]\n        )\n        corrected["alertes_finales"] = ""\n        corrected["nombre_alertes_finales"] = 0\n        corrected["statut_final"] = "prevalide_unite_unique_meme_page"\n        corrected["methode_validation"] = (\n            "unité unique observée sur la même page du PDF"\n        )\n        inferred_rows.append(corrected)\n\n    inferred = pd.DataFrame(inferred_rows)\n    common = sorted(set(base.columns) | set(inferred.columns))\n    for column in common:\n        if column not in base:\n            base[column] = pd.NA\n        if column not in inferred:\n            inferred[column] = pd.NA\n    combined = pd.concat([base[common], inferred[common]], ignore_index=True)\n    combined.sort_values(KEYS, inplace=True)\n    combined.drop_duplicates(KEYS, keep="first", inplace=True)\n\n    inferred_keys = inferred[KEYS].assign(inferee=True)\n    remaining_v3 = remaining.merge(inferred_keys, on=KEYS, how="left")\n    remaining_v3 = remaining_v3[remaining_v3["inferee"].isna()].drop(columns=["inferee"])\n    wide = combined.pivot_table(\n        index=["societe", "secteur", "annee", "type_comptes_resolu"],\n        columns="variable",\n        values="valeur_mad",\n        aggfunc="first",\n    ).reset_index()\n    counts = (\n        combined.groupby(["societe", "annee", "type_comptes_resolu"])["variable"]\n        .nunique()\n        .rename("nombre_variables_prevalidees")\n        .reset_index()\n    )\n    wide = wide.merge(counts, on=["societe", "annee", "type_comptes_resolu"], how="left")\n\n    summary = pd.DataFrame(\n        {\n            "indicateur": [\n                "valeurs base v2",\n                "unités inférées même page",\n                "valeurs base v3",\n                "candidats prioritaires restants",\n            ],\n            "valeur": [len(base), len(inferred), len(combined), len(remaining_v3)],\n        }\n    )\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        wide.to_excel(writer, sheet_name="Base prévalidée large", index=False)\n        combined.to_excel(writer, sheet_name="Valeurs prévalidées", index=False)\n        inferred.to_excel(writer, sheet_name="Ajouts unités même page", index=False)\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n    with pd.ExcelWriter(REMAINING_OUTPUT, engine="openpyxl") as writer:\n        remaining_v3.to_excel(writer, sheet_name="Candidats restants", index=False)\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n    print(summary.to_string(index=False))\n    print(f"Base v3 : {OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '18_prepare_rcai_manual_review.py': '"""Prépare le contrôle page par page du résultat avant impôt."""\n\nfrom __future__ import annotations\n\nimport re\nfrom pathlib import Path\n\nimport fitz\nimport pandas as pd\n\n\nBASE_DIR = Path(__file__).resolve().parent\nSOURCE = BASE_DIR / "data" / "output" / "lots_controle_prioritaire_restants_v3.xlsx"\nOUTPUT = BASE_DIR / "data" / "output" / "controle_manuel_resultat_avant_impot.xlsx"\nILLEGAL_EXCEL_RE = re.compile(r"[\\x00-\\x08\\x0b-\\x0c\\x0e-\\x1f]")\n\n\ndef page_context(source_pdf: str, page_number: int) -> str:\n    path = BASE_DIR / str(source_pdf)\n    try:\n        document = fitz.open(path)\n        text = document[int(page_number) - 1].get_text("text")\n        document.close()\n    except Exception as error:\n        return f"ERREUR LECTURE : {error}"\n    lines = [line.strip() for line in text.splitlines() if line.strip()]\n    contexts = []\n    for index, line in enumerate(lines):\n        if re.search(r"résultat\\s+(?:courant\\s+)?avant\\s+imp|resultat\\s+(?:courant\\s+)?avant\\s+imp", line, re.I):\n            contexts.append(" | ".join(lines[max(0, index - 8): index + 12]))\n    return " || ".join(contexts)[:5000]\n\n\ndef main() -> None:\n    data = pd.read_excel(SOURCE, sheet_name=0)\n    data = data[data["variable"].eq("resultat_avant_impot")].copy()\n    data.sort_values(\n        ["nombre_alertes_finales", "score_classement", "societe", "annee"],\n        ascending=[True, False, True, True],\n        inplace=True,\n    )\n    data["contexte_page_rcai"] = data.apply(\n        lambda row: page_context(row["source_pdf"], row["page_pdf"]),\n        axis=1,\n    )\n    data["decision_finale"] = ""\n    data["valeur_finale_mad"] = pd.NA\n    data["commentaire_validation"] = ""\n    data["chemin_pdf_absolu"] = data["source_pdf"].map(\n        lambda value: str(BASE_DIR / str(value))\n    )\n    for column in data.select_dtypes(include="object").columns:\n        data[column] = data[column].map(\n            lambda value: ILLEGAL_EXCEL_RE.sub("", value)\n            if isinstance(value, str)\n            else value\n        )\n    data.to_excel(OUTPUT, index=False)\n    print(f"Candidats RCAI : {len(data)}")\n    print(\n        "Valeurs distinctes à compléter : "\n        f"{len(data.drop_duplicates([\'societe\', \'annee\', \'type_comptes_resolu\', \'variable\']))}"\n    )\n    print(f"Sortie : {OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '19_accept_explicit_rcai_units.py': 'from pathlib import Path\n\nimport pandas as pd\n\n\nOUTPUT_DIR = Path("data/output")\nSOURCE_BASE = OUTPUT_DIR / "variables_financieres_base_prevalidee_v3.xlsx"\nSOURCE_REVIEW = OUTPUT_DIR / "controle_manuel_resultat_avant_impot.xlsx"\nOUTPUT_BASE = OUTPUT_DIR / "variables_financieres_base_prevalidee_v4.xlsx"\nOUTPUT_REMAINING = OUTPUT_DIR / "controle_manuel_resultat_avant_impot_restant_v4.xlsx"\n\n# Cas vérifiés dans le contexte de la page : l\'unité est explicitement indiquée\n# et l\'unique alerte est « unité inconnue ».\nSAFE_KEYS = {\n    ("Attijari wafa bank", 2012, "sociaux"): 1_000,\n    ("Attijari wafa bank", 2013, "sociaux"): 1_000,\n    ("CIH", 2025, "sociaux"): 1_000,\n}\n\n\ndef main() -> None:\n    wide = pd.read_excel(SOURCE_BASE, sheet_name="Base prévalidée large")\n    values = pd.read_excel(SOURCE_BASE, sheet_name="Valeurs prévalidées")\n    previous_additions = pd.read_excel(\n        SOURCE_BASE, sheet_name="Ajouts unités même page"\n    )\n    review = pd.read_excel(SOURCE_REVIEW)\n\n    selected_rows = []\n    for index, row in review.iterrows():\n        key = (\n            str(row["societe"]),\n            int(row["annee"]),\n            str(row["type_comptes_resolu"]),\n        )\n        if key not in SAFE_KEYS:\n            continue\n        if str(row["alertes_finales"]).strip() != "unité inconnue":\n            raise ValueError(f"Alerte inattendue pour {key}: {row[\'alertes_finales\']}")\n\n        multiplier = SAFE_KEYS[key]\n        accepted = row.copy()\n        accepted["unite"] = "milliers MAD"\n        accepted["multiplicateur_mad"] = multiplier\n        accepted["valeur_mad"] = float(row["valeur_numerique"]) * multiplier\n        accepted["valeur_corrigee_mad"] = accepted["valeur_mad"]\n        accepted["methode_validation"] = "unité explicite vérifiée dans la page"\n        accepted["statut_final"] = "prevalide"\n        accepted["alertes_finales"] = ""\n        accepted["nombre_alertes_finales"] = 0\n        accepted["alerte_severe"] = False\n        selected_rows.append(accepted)\n\n    additions = pd.DataFrame(selected_rows)\n    if len(additions) != len(SAFE_KEYS):\n        raise ValueError(\n            f"{len(additions)} cas trouvés au lieu de {len(SAFE_KEYS)} cas attendus"\n        )\n\n    additions = additions.reindex(columns=values.columns)\n    combined = pd.concat([values, additions], ignore_index=True)\n    key_columns = ["societe", "annee", "type_comptes_resolu", "variable"]\n    combined = combined.drop_duplicates(key_columns, keep="last")\n\n    pivot = combined.pivot_table(\n        index=["societe", "secteur", "annee", "type_comptes_resolu"],\n        columns="variable",\n        values="valeur_mad",\n        aggfunc="first",\n    ).reset_index()\n    pivot.columns.name = None\n    variable_columns = [\n        column\n        for column in pivot.columns\n        if column not in ["societe", "secteur", "annee", "type_comptes_resolu"]\n    ]\n    pivot["nombre_variables_prevalidees"] = pivot[variable_columns].notna().sum(axis=1)\n\n    selected_indices = {\n        index\n        for index, row in review.iterrows()\n        if (\n            str(row["societe"]),\n            int(row["annee"]),\n            str(row["type_comptes_resolu"]),\n        )\n        in SAFE_KEYS\n    }\n    remaining = review.drop(index=list(selected_indices)).copy()\n\n    summary = pd.DataFrame(\n        {\n            "indicateur": [\n                "Valeurs prévalidées V4",\n                "Nouveaux RCAI acceptés",\n                "Observations société-année-type",\n                "Entreprises représentées",\n                "RCAI restant à contrôler",\n            ],\n            "valeur": [\n                len(combined),\n                len(additions),\n                len(pivot),\n                pivot["societe"].nunique(),\n                len(remaining),\n            ],\n        }\n    )\n\n    with pd.ExcelWriter(OUTPUT_BASE, engine="openpyxl") as writer:\n        pivot.to_excel(writer, sheet_name="Base prévalidée large", index=False)\n        combined.to_excel(writer, sheet_name="Valeurs prévalidées", index=False)\n        previous_additions.to_excel(\n            writer, sheet_name="Ajouts unités même page", index=False\n        )\n        additions.to_excel(writer, sheet_name="Ajouts RCAI unité explicite", index=False)\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n\n    remaining.to_excel(OUTPUT_REMAINING, index=False)\n    print(summary.to_string(index=False))\n    print(f"\\nCréé : {OUTPUT_BASE}")\n    print(f"Créé : {OUTPUT_REMAINING}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '20_validate_rcai_with_is.py': 'from difflib import SequenceMatcher\nfrom pathlib import Path\nimport re\nimport unicodedata\n\nimport pandas as pd\n\n\nINPUT_DIR = Path("data/input")\nOUTPUT_DIR = Path("data/output")\nIS_FILE = next(INPUT_DIR.glob("IS*.xlsx"))\nBASE_V4 = OUTPUT_DIR / "variables_financieres_base_prevalidee_v4.xlsx"\nREVIEW_V4 = OUTPUT_DIR / "controle_manuel_resultat_avant_impot_restant_v4.xlsx"\nBASE_V5 = OUTPUT_DIR / "variables_financieres_base_prevalidee_v5.xlsx"\nREVIEW_V5 = OUTPUT_DIR / "controle_manuel_resultat_avant_impot_restant_v5.xlsx"\nAUDIT_FILE = OUTPUT_DIR / "audit_validation_rcai_par_is.xlsx"\n\nALIASES = {\n    "AGMA": "AGMA-LAHLOU-TAZI",\n    "ALLIANCES": "ALLIANCES Développement Immobilier (ADI)",\n    "Addoha": "Douja PRO ADDOHA",\n    "Brasseries du Maroc": "SOCIETE DES Boissons DU MAROC (SBM)",\n    "Lesieur cristal": "Lesieur",\n    "SRM": "Société de Réalisation Mécanique (SRM SA)",\n    "SCE": "Société Cherifiènne d\'Engrais",\n}\n\n\ndef normalize(text):\n    text = unicodedata.normalize("NFKD", str(text))\n    text = text.encode("ascii", "ignore").decode().lower()\n    return " ".join(re.sub(r"[^a-z0-9]+", " ", text).split())\n\n\ndef best_is_name(company, names):\n    if company in ALIASES:\n        return ALIASES[company], 1.0\n    company_norm = normalize(company)\n    ranked = sorted(\n        (\n            (SequenceMatcher(None, company_norm, normalize(name)).ratio(), name)\n            for name in names\n        ),\n        reverse=True,\n    )\n    score, name = ranked[0]\n    return name, score\n\n\ndef main():\n    is_wide = pd.read_excel(IS_FILE, sheet_name=0, header=2)\n    company_column = is_wide.columns[0]\n    is_long = is_wide.melt(\n        id_vars=[company_column], var_name="annee", value_name="is_mad"\n    ).rename(columns={company_column: "societe_is"})\n    is_long["annee"] = pd.to_numeric(is_long["annee"], errors="coerce")\n    is_long["is_mad"] = pd.to_numeric(is_long["is_mad"], errors="coerce")\n    is_long = is_long.dropna(subset=["societe_is", "annee", "is_mad"])\n    is_long["annee"] = is_long["annee"].astype(int)\n\n    review = pd.read_excel(REVIEW_V4)\n    values = pd.read_excel(BASE_V4, sheet_name="Valeurs prévalidées")\n    workbook = {\n        sheet: pd.read_excel(BASE_V4, sheet_name=sheet)\n        for sheet in pd.ExcelFile(BASE_V4).sheet_names\n    }\n\n    is_names = list(is_long["societe_is"].unique())\n    matches = review["societe"].map(lambda value: best_is_name(value, is_names))\n    review["societe_is"] = matches.map(lambda value: value[0])\n    review["score_correspondance_nom"] = matches.map(lambda value: value[1])\n\n    net = values.loc[\n        values["variable"].eq("resultat_net"),\n        ["societe", "annee", "type_comptes_resolu", "valeur_mad"],\n    ].rename(columns={"valeur_mad": "resultat_net_mad"})\n\n    audit = review.merge(\n        is_long, on=["societe_is", "annee"], how="left"\n    ).merge(net, on=["societe", "annee", "type_comptes_resolu"], how="left")\n    audit["rcai_theorique_mad"] = audit["resultat_net_mad"] + audit["is_mad"]\n\n    multipliers = (1, 1_000, 1_000_000)\n    for multiplier in multipliers:\n        audit[f"ecart_relatif_x{multiplier}"] = (\n            audit["valeur_numerique"] * multiplier - audit["rcai_theorique_mad"]\n        ).abs() / audit["rcai_theorique_mad"].abs().clip(lower=1)\n\n    error_columns = [f"ecart_relatif_x{m}" for m in multipliers]\n    audit["ecart_relatif_min"] = audit[error_columns].min(axis=1)\n    audit["multiplicateur_retenu"] = audit[error_columns].apply(\n        lambda row: (\n            multipliers[int(row.values.argmin())] if row.notna().any() else pd.NA\n        ),\n        axis=1,\n    )\n    audit["part_resultat_net"] = (\n        audit["resultat_net_mad"].abs()\n        / audit["rcai_theorique_mad"].abs().clip(lower=1)\n    )\n\n    audit["validation_automatique"] = (\n        audit["is_mad"].notna()\n        & audit["resultat_net_mad"].notna()\n        & audit["score_correspondance_nom"].ge(0.60)\n        & audit["alertes_finales"].fillna("").eq("unité inconnue")\n        & audit["ecart_relatif_min"].le(0.002)\n        & audit["part_resultat_net"].ge(0.05)\n    )\n\n    accepted_audit = audit.loc[audit["validation_automatique"]].copy()\n    accepted = accepted_audit[review.columns].copy()\n    accepted["multiplicateur_mad"] = accepted_audit[\n        "multiplicateur_retenu"\n    ].astype(float).values\n    accepted["valeur_mad"] = (\n        accepted["valeur_numerique"] * accepted["multiplicateur_mad"]\n    )\n    accepted["valeur_corrigee_mad"] = accepted["valeur_mad"]\n    accepted["unite"] = accepted["multiplicateur_mad"].map(\n        {1: "MAD", 1_000: "milliers MAD", 1_000_000: "millions MAD"}\n    )\n    accepted["alertes_finales"] = ""\n    accepted["nombre_alertes_finales"] = 0\n    accepted["alerte_severe"] = False\n    accepted["statut_final"] = "prevalide"\n    accepted["methode_validation"] = "RCAI vérifié par résultat net + IS"\n\n    accepted_for_values = accepted.reindex(columns=values.columns)\n    combined = pd.concat([values, accepted_for_values], ignore_index=True)\n    key = ["societe", "annee", "type_comptes_resolu", "variable"]\n    combined = combined.drop_duplicates(key, keep="last")\n\n    pivot = combined.pivot_table(\n        index=["societe", "secteur", "annee", "type_comptes_resolu"],\n        columns="variable",\n        values="valeur_mad",\n        aggfunc="first",\n    ).reset_index()\n    pivot.columns.name = None\n    identifiers = ["societe", "secteur", "annee", "type_comptes_resolu"]\n    pivot["nombre_variables_prevalidees"] = pivot[\n        [column for column in pivot.columns if column not in identifiers]\n    ].notna().sum(axis=1)\n\n    accepted_indices = set(accepted_audit.index)\n    remaining = review.drop(index=list(accepted_indices)).copy()\n    summary = pd.DataFrame(\n        {\n            "indicateur": [\n                "Valeurs prévalidées V5",\n                "Nouveaux RCAI validés par IS",\n                "Observations société-année-type",\n                "Entreprises représentées",\n                "RCAI restant à contrôler",\n            ],\n            "valeur": [\n                len(combined),\n                len(accepted),\n                len(pivot),\n                pivot["societe"].nunique(),\n                len(remaining),\n            ],\n        }\n    )\n\n    with pd.ExcelWriter(BASE_V5, engine="openpyxl") as writer:\n        pivot.to_excel(writer, sheet_name="Base prévalidée large", index=False)\n        combined.to_excel(writer, sheet_name="Valeurs prévalidées", index=False)\n        for sheet, frame in workbook.items():\n            if sheet not in {"Base prévalidée large", "Valeurs prévalidées", "Résumé"}:\n                frame.to_excel(writer, sheet_name=sheet[:31], index=False)\n        accepted.to_excel(writer, sheet_name="Ajouts RCAI vérifiés IS", index=False)\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n\n    remaining.to_excel(REVIEW_V5, index=False)\n    with pd.ExcelWriter(AUDIT_FILE, engine="openpyxl") as writer:\n        audit.to_excel(writer, sheet_name="Tous les rapprochements", index=False)\n        accepted_audit.to_excel(writer, sheet_name="Validés automatiquement", index=False)\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n\n    print(summary.to_string(index=False))\n    print("\\nCas validés :")\n    print(\n        accepted_audit[\n            [\n                "societe",\n                "annee",\n                "type_comptes_resolu",\n                "is_mad",\n                "resultat_net_mad",\n                "rcai_theorique_mad",\n                "ecart_relatif_min",\n            ]\n        ].to_string(index=False)\n    )\n    print(f"\\nCréé : {BASE_V5}")\n    print(f"Créé : {REVIEW_V5}")\n    print(f"Créé : {AUDIT_FILE}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '21_correct_rcai_total_column.py': 'from pathlib import Path\n\nimport pandas as pd\n\n\nOUTPUT_DIR = Path("data/output")\nBASE_V5 = OUTPUT_DIR / "variables_financieres_base_prevalidee_v5.xlsx"\nREVIEW_V5 = OUTPUT_DIR / "controle_manuel_resultat_avant_impot_restant_v5.xlsx"\nBASE_V6 = OUTPUT_DIR / "variables_financieres_base_prevalidee_v6.xlsx"\nREVIEW_V6 = OUTPUT_DIR / "controle_manuel_resultat_avant_impot_restant_v6.xlsx"\n\n# Montants de la colonne « total exercice » relus dans la ligne RCAI du PDF.\nCORRECTIONS = {\n    ("SMI", 2025, "sociaux"): 588_164_741.01,\n    ("MINIERE TOUISSIT", 2011, "sociaux"): 448_015_453.49,\n    ("CTM", 2011, "sociaux"): 38_799_338.42,\n}\n\n\ndef main():\n    workbook = {\n        sheet: pd.read_excel(BASE_V5, sheet_name=sheet)\n        for sheet in pd.ExcelFile(BASE_V5).sheet_names\n    }\n    values = workbook["Valeurs prévalidées"]\n    review = pd.read_excel(REVIEW_V5)\n\n    selected = []\n    selected_indices = []\n    for index, row in review.iterrows():\n        key = (\n            str(row["societe"]),\n            int(row["annee"]),\n            str(row["type_comptes_resolu"]),\n        )\n        if key not in CORRECTIONS:\n            continue\n        accepted = row.copy()\n        accepted["valeur_corrigee_mad"] = CORRECTIONS[key]\n        accepted["valeur_mad"] = CORRECTIONS[key]\n        accepted["unite"] = "MAD"\n        accepted["multiplicateur_mad"] = 1\n        accepted["alertes_finales"] = ""\n        accepted["nombre_alertes_finales"] = 0\n        accepted["alerte_severe"] = False\n        accepted["statut_final"] = "prevalide"\n        accepted["methode_validation"] = (\n            "colonne total exercice relue; vérifiée par résultat net + IS"\n        )\n        selected.append(accepted)\n        selected_indices.append(index)\n\n    additions = pd.DataFrame(selected)\n    if len(additions) != len(CORRECTIONS):\n        raise ValueError(\n            f"{len(additions)} corrections trouvées au lieu de {len(CORRECTIONS)}"\n        )\n\n    additions_for_values = additions.reindex(columns=values.columns)\n    combined = pd.concat([values, additions_for_values], ignore_index=True)\n    key_columns = ["societe", "annee", "type_comptes_resolu", "variable"]\n    combined = combined.drop_duplicates(key_columns, keep="last")\n\n    pivot = combined.pivot_table(\n        index=["societe", "secteur", "annee", "type_comptes_resolu"],\n        columns="variable",\n        values="valeur_mad",\n        aggfunc="first",\n    ).reset_index()\n    pivot.columns.name = None\n    identifiers = ["societe", "secteur", "annee", "type_comptes_resolu"]\n    pivot["nombre_variables_prevalidees"] = pivot[\n        [column for column in pivot.columns if column not in identifiers]\n    ].notna().sum(axis=1)\n\n    remaining = review.drop(index=selected_indices).copy()\n    summary = pd.DataFrame(\n        {\n            "indicateur": [\n                "Valeurs prévalidées V6",\n                "RCAI corrigés colonne total",\n                "Observations société-année-type",\n                "Entreprises représentées",\n                "RCAI restant à contrôler",\n            ],\n            "valeur": [\n                len(combined),\n                len(additions),\n                len(pivot),\n                pivot["societe"].nunique(),\n                len(remaining),\n            ],\n        }\n    )\n\n    with pd.ExcelWriter(BASE_V6, engine="openpyxl") as writer:\n        pivot.to_excel(writer, sheet_name="Base prévalidée large", index=False)\n        combined.to_excel(writer, sheet_name="Valeurs prévalidées", index=False)\n        for sheet, frame in workbook.items():\n            if sheet not in {"Base prévalidée large", "Valeurs prévalidées", "Résumé"}:\n                frame.to_excel(writer, sheet_name=sheet, index=False)\n        additions.to_excel(writer, sheet_name="Corrections RCAI total", index=False)\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n\n    remaining.to_excel(REVIEW_V6, index=False)\n    print(summary.to_string(index=False))\n    print("\\nCorrections :")\n    print(\n        additions[\n            ["societe", "annee", "type_comptes_resolu", "valeur_mad", "source_pdf"]\n        ].to_string(index=False)\n    )\n    print(f"\\nCréé : {BASE_V6}")\n    print(f"Créé : {REVIEW_V6}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '22_accept_structural_rcai_totals.py': 'from pathlib import Path\nimport re\n\nimport pandas as pd\n\n\nOUTPUT_DIR = Path("data/output")\nBASE_SOURCE = OUTPUT_DIR / "variables_financieres_base_prevalidee_v6.xlsx"\nREVIEW_SOURCE = OUTPUT_DIR / "controle_manuel_resultat_avant_impot_restant_v6.xlsx"\nBASE_OUTPUT = OUTPUT_DIR / "variables_financieres_base_prevalidee_v7.xlsx"\nREVIEW_OUTPUT = OUTPUT_DIR / "controle_manuel_resultat_avant_impot_restant_v7.xlsx"\n\nNUMBER_PATTERN = re.compile(\n    r"\\(?-?\\d[\\d .\\u202f\\u00a0]*(?:,\\d+)?\\)?"\n)\n\n\ndef parse_number(raw):\n    text = str(raw).strip().replace("\\u202f", " ").replace("\\u00a0", " ")\n    negative = text.startswith("(") and text.endswith(")")\n    text = text.strip("()").replace(" ", "")\n    if "," in text:\n        text = text.replace(".", "").replace(",", ".")\n    else:\n        parts = text.split(".")\n        if len(parts) > 2 or (len(parts) == 2 and len(parts[-1]) == 3):\n            text = "".join(parts)\n    try:\n        value = float(text)\n        return -value if negative else value\n    except ValueError:\n        return None\n\n\ndef structural_total(line):\n    numbers = []\n    for token in NUMBER_PATTERN.findall(str(line)):\n        value = parse_number(token)\n        if value is not None and abs(value) > 100:\n            numbers.append(value)\n    if len(numbers) < 3:\n        return None\n    first, second, total = numbers[:3]\n    relative_error = abs((first + second) - total) / max(abs(total), 1)\n    return total if relative_error <= 1e-9 else None\n\n\ndef main():\n    workbook = {\n        sheet: pd.read_excel(BASE_SOURCE, sheet_name=sheet)\n        for sheet in pd.ExcelFile(BASE_SOURCE).sheet_names\n    }\n    values = workbook["Valeurs prévalidées"]\n    review = pd.read_excel(REVIEW_SOURCE)\n\n    selected = []\n    selected_indices = []\n    for index, row in review.iterrows():\n        total = structural_total(row["ligne_tableau"])\n        safe = (\n            total is not None\n            and int(row["annee"]) == int(row["annee_rapport"])\n            and str(row["type_comptes_resolu"]) == "sociaux"\n            and str(row["alertes_finales"]).strip() == "unité inconnue"\n            and abs(float(row["valeur_mad"]) - total) / max(abs(total), 1) > 1e-6\n        )\n        if not safe:\n            continue\n        accepted = row.copy()\n        accepted["valeur_mad"] = total\n        accepted["valeur_corrigee_mad"] = total\n        accepted["unite"] = "MAD"\n        accepted["multiplicateur_mad"] = 1\n        accepted["alertes_finales"] = ""\n        accepted["nombre_alertes_finales"] = 0\n        accepted["alerte_severe"] = False\n        accepted["statut_final"] = "prevalide"\n        accepted["methode_validation"] = (\n            "total exercice = première composante + seconde composante"\n        )\n        selected.append(accepted)\n        selected_indices.append(index)\n\n    additions = pd.DataFrame(selected)\n    additions_for_values = additions.reindex(columns=values.columns)\n    combined = pd.concat([values, additions_for_values], ignore_index=True)\n    key_columns = ["societe", "annee", "type_comptes_resolu", "variable"]\n    combined = combined.drop_duplicates(key_columns, keep="last")\n\n    pivot = combined.pivot_table(\n        index=["societe", "secteur", "annee", "type_comptes_resolu"],\n        columns="variable",\n        values="valeur_mad",\n        aggfunc="first",\n    ).reset_index()\n    pivot.columns.name = None\n    identifiers = ["societe", "secteur", "annee", "type_comptes_resolu"]\n    pivot["nombre_variables_prevalidees"] = pivot[\n        [column for column in pivot.columns if column not in identifiers]\n    ].notna().sum(axis=1)\n    remaining = review.drop(index=selected_indices).copy()\n\n    summary = pd.DataFrame(\n        {\n            "indicateur": [\n                "Valeurs prévalidées V7",\n                "RCAI structurels corrigés",\n                "Observations société-année-type",\n                "Entreprises représentées",\n                "RCAI restant à contrôler",\n            ],\n            "valeur": [\n                len(combined),\n                len(additions),\n                len(pivot),\n                pivot["societe"].nunique(),\n                len(remaining),\n            ],\n        }\n    )\n\n    with pd.ExcelWriter(BASE_OUTPUT, engine="openpyxl") as writer:\n        pivot.to_excel(writer, sheet_name="Base prévalidée large", index=False)\n        combined.to_excel(writer, sheet_name="Valeurs prévalidées", index=False)\n        for sheet, frame in workbook.items():\n            if sheet not in {"Base prévalidée large", "Valeurs prévalidées", "Résumé"}:\n                frame.to_excel(writer, sheet_name=sheet, index=False)\n        additions.to_excel(writer, sheet_name="Ajouts RCAI structurels", index=False)\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n\n    remaining.to_excel(REVIEW_OUTPUT, index=False)\n    print(summary.to_string(index=False))\n    print("\\nAjouts :")\n    print(\n        additions[\n            ["societe", "annee", "type_comptes_resolu", "valeur_mad"]\n        ].to_string(index=False)\n    )\n    print(f"\\nCréé : {BASE_OUTPUT}")\n    print(f"Créé : {REVIEW_OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '23_accept_comparative_rcai_totals.py': 'from pathlib import Path\nimport re\n\nimport pandas as pd\n\n\nOUTPUT_DIR = Path("data/output")\nBASE_SOURCE = OUTPUT_DIR / "variables_financieres_base_prevalidee_v7.xlsx"\nREVIEW_SOURCE = OUTPUT_DIR / "controle_manuel_resultat_avant_impot_restant_v7.xlsx"\nBASE_OUTPUT = OUTPUT_DIR / "variables_financieres_base_prevalidee_v8.xlsx"\nREVIEW_OUTPUT = OUTPUT_DIR / "controle_manuel_resultat_avant_impot_restant_v8.xlsx"\n\nNUMBER_PATTERN = re.compile(r"\\(?-?\\d[\\d .\\u202f\\u00a0]*(?:,\\d+)?\\)?")\n\n\ndef parse_number(raw):\n    text = str(raw).strip().replace("\\u202f", " ").replace("\\u00a0", " ")\n    negative = text.startswith("(") and text.endswith(")")\n    text = text.strip("()").replace(" ", "")\n    if "," in text:\n        text = text.replace(".", "").replace(",", ".")\n    else:\n        parts = text.split(".")\n        if len(parts) > 2 or (len(parts) == 2 and len(parts[-1]) == 3):\n            text = "".join(parts)\n    try:\n        value = float(text)\n        return -value if negative else value\n    except ValueError:\n        return None\n\n\ndef comparative_total(line):\n    numbers = []\n    for token in NUMBER_PATTERN.findall(str(line)):\n        value = parse_number(token)\n        if value is not None and abs(value) > 100:\n            numbers.append(value)\n    if len(numbers) < 4:\n        return None\n    first, second, current_total, previous_total = numbers[:4]\n    relative_error = abs((first + second) - current_total) / max(\n        abs(current_total), 1\n    )\n    return previous_total if relative_error <= 1e-9 else None\n\n\ndef main():\n    workbook = {\n        sheet: pd.read_excel(BASE_SOURCE, sheet_name=sheet)\n        for sheet in pd.ExcelFile(BASE_SOURCE).sheet_names\n    }\n    values = workbook["Valeurs prévalidées"]\n    review = pd.read_excel(REVIEW_SOURCE)\n\n    selected = []\n    selected_indices = []\n    for index, row in review.iterrows():\n        total = comparative_total(row["ligne_tableau"])\n        safe = (\n            total is not None\n            and int(row["annee_rapport"]) == int(row["annee"]) + 1\n            and str(row["type_comptes_resolu"]) == "sociaux"\n            and str(row["alertes_finales"]).strip() == "unité inconnue"\n            and abs(float(row["valeur_mad"]) - total) / max(abs(total), 1) > 1e-6\n        )\n        if not safe:\n            continue\n        accepted = row.copy()\n        accepted["valeur_mad"] = total\n        accepted["valeur_corrigee_mad"] = total\n        accepted["unite"] = "MAD"\n        accepted["multiplicateur_mad"] = 1\n        accepted["alertes_finales"] = ""\n        accepted["nombre_alertes_finales"] = 0\n        accepted["alerte_severe"] = False\n        accepted["statut_final"] = "prevalide"\n        accepted["methode_validation"] = (\n            "colonne comparative N du rapport N+1; structure arithmétique vérifiée"\n        )\n        selected.append(accepted)\n        selected_indices.append(index)\n\n    additions = pd.DataFrame(selected)\n    additions_for_values = additions.reindex(columns=values.columns)\n    combined = pd.concat([values, additions_for_values], ignore_index=True)\n    key_columns = ["societe", "annee", "type_comptes_resolu", "variable"]\n    combined = combined.drop_duplicates(key_columns, keep="last")\n\n    pivot = combined.pivot_table(\n        index=["societe", "secteur", "annee", "type_comptes_resolu"],\n        columns="variable",\n        values="valeur_mad",\n        aggfunc="first",\n    ).reset_index()\n    pivot.columns.name = None\n    identifiers = ["societe", "secteur", "annee", "type_comptes_resolu"]\n    pivot["nombre_variables_prevalidees"] = pivot[\n        [column for column in pivot.columns if column not in identifiers]\n    ].notna().sum(axis=1)\n    remaining = review.drop(index=selected_indices).copy()\n\n    summary = pd.DataFrame(\n        {\n            "indicateur": [\n                "Valeurs prévalidées V8",\n                "RCAI comparatifs corrigés",\n                "Observations société-année-type",\n                "Entreprises représentées",\n                "RCAI restant à contrôler",\n            ],\n            "valeur": [\n                len(combined),\n                len(additions),\n                len(pivot),\n                pivot["societe"].nunique(),\n                len(remaining),\n            ],\n        }\n    )\n\n    with pd.ExcelWriter(BASE_OUTPUT, engine="openpyxl") as writer:\n        pivot.to_excel(writer, sheet_name="Base prévalidée large", index=False)\n        combined.to_excel(writer, sheet_name="Valeurs prévalidées", index=False)\n        for sheet, frame in workbook.items():\n            if sheet not in {"Base prévalidée large", "Valeurs prévalidées", "Résumé"}:\n                frame.to_excel(writer, sheet_name=sheet, index=False)\n        additions.to_excel(writer, sheet_name="Ajouts RCAI comparatifs", index=False)\n        summary.to_excel(writer, sheet_name="Résumé", index=False)\n\n    remaining.to_excel(REVIEW_OUTPUT, index=False)\n    print(summary.to_string(index=False))\n    print("\\nAjouts :")\n    if not additions.empty:\n        print(\n            additions[\n                ["societe", "annee", "annee_rapport", "type_comptes_resolu", "valeur_mad"]\n            ].to_string(index=False)\n        )\n    print(f"\\nCréé : {BASE_OUTPUT}")\n    print(f"Créé : {REVIEW_OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    'diagnostic_taille.py': '"""\nDiagnostic rapide : affiche le HTML brut autour du lien PDF sur une fiche AMMC,\npour comprendre pourquoi la taille de fichier n\'est pas extraite.\n"""\nimport requests\nfrom bs4 import BeautifulSoup\n\nURL_TEST = "https://www.ammc.ma/fr/espace-emetteurs/etats-financiers/cosumar-rfa-2023"\nHEADERS = {"User-Agent": "Mozilla/5.0 (compatible; DiagnosticAcademique/1.0)"}\n\nresp = requests.get(URL_TEST, headers=HEADERS, timeout=20)\nsoup = BeautifulSoup(resp.text, "html.parser")\n\nfor a in soup.find_all("a", href=True):\n    if a["href"].lower().endswith(".pdf"):\n        print("=== Lien PDF trouvé ===")\n        print("href:", a["href"])\n        print("texte du lien:", repr(a.get_text()))\n        print()\n        print("=== HTML du parent (td) ===")\n        print(a.parent)\n        print()\n        print("=== Texte brut du parent ===")\n        print(repr(a.parent.get_text(" ", strip=True)))\n        print()\n        print("=== HTML du grand-parent (tr) ===")\n        print(a.parent.parent)\n        break\nelse:\n    print("Aucun lien .pdf trouvé sur la page.")\n',
}


def list_scripts() -> None:
    """Affiche les étapes historiques disponibles dans ce regroupement."""
    for script_name in sorted(SCRIPTS):
        print(script_name)


def run_script(script_name: str) -> None:
    """Exécute un script historique dans un espace de noms isolé."""
    normalized = script_name if script_name.endswith(".py") else f"{script_name}.py"
    if normalized not in SCRIPTS:
        choices = ", ".join(sorted(SCRIPTS))
        raise SystemExit(f"Script inconnu : {script_name}\nChoix disponibles : {choices}")

    previous_directory = Path.cwd()
    os.chdir(PROJECT_ROOT)
    namespace = {
        "__name__": "__main__",
        "__file__": str(PROJECT_ROOT / normalized),
        "__package__": None,
    }
    try:
        source = SCRIPTS[normalized]
        exec(compile(source, namespace["__file__"], "exec"), namespace)
    finally:
        os.chdir(previous_directory)


def main() -> None:
    """Afficher le catalogue interne ou exécuter le diagnostic demandé."""
    parser = argparse.ArgumentParser(
        description="Lister ou exécuter une étape historique regroupée."
    )
    parser.add_argument("script", nargs="?", help="Nom du script à exécuter.")
    parser.add_argument(
        "--list", action="store_true", help="Afficher les scripts disponibles."
    )
    args = parser.parse_args()

    if args.list or not args.script:
        list_scripts()
        return
    run_script(args.script)


if __name__ == "__main__":
    main()
